  Lemma vt_facts :
    fldA m v 8 b /\ fldA m (v + 8) 8 (b + 4 * Zlen xs) /\ fldA m (v + 16) 8 (b + 4 * cap)
    /\ (forall i, 0 <= i < Zlen xs -> 0 <= Znth i xs < 2 ^ 32 /\ fldA m (b + 4 * i) 4 (Znth i xs))
